using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* Column Schedule Formatter window: the same layout as the Beam and Slab Formatters (title, one command row, Loaded DXF line, notes,
   Schedule values / DXF preview, selected row details) */
class ColumnFormatterForm:Form {
 readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells};
 readonly TextBox prefix=new TextBox{Width=85,Text="C",CharacterCasing=CharacterCasing.Upper},title=new TextBox{Width=240,Text="",CharacterCasing=CharacterCasing.Upper};readonly CheckBox merge=new CheckBox{Text="Merge identical columns",Checked=true,AutoSize=true},elevations=new CheckBox{Text="Column elevations",Checked=true,AutoSize=true};
 readonly Label source=new Label{Dock=DockStyle.Top,Height=45,Padding=new Padding(12),Text="Loaded DXF: none",Font=ModernUi.Body};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=34,Padding=new Padding(18,8,8,0),Text="Ready. Load the column schedule DXF exported from STAAD RCDC / AutoCAD."};
 readonly PictureBox cad=new PictureBox{SizeMode=PictureBoxSizeMode.AutoSize};readonly Button export=new Button{Text="Export revised DXF",AutoSize=true,Enabled=false};readonly TextBox details=new TextBox{Dock=DockStyle.Bottom,Height=92,Multiline=true,ReadOnly=true,BorderStyle=BorderStyle.None,BackColor=Color.FromArgb(237,243,248),Font=new Font("Consolas",9.5f),ScrollBars=ScrollBars.Both,WordWrap=false,Text="Select a row to review its original column marks."};
 readonly ComboBox detailing=AciDetailing.Combo();readonly ComboBox lapPosition=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=180,Margin=new Padding(6,6,10,0)};readonly ComboBox extraTies=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=200,Margin=new Padding(6,6,10,0)};string raw;ColumnFormatResult result;bool busy;
 public ColumnFormatterForm(){if(!AccessCodes.CanUseApp(ProgramAccess.SlabFormatter))throw new Exception("Schedule Formatter access required.");AppBrand.Apply(this);Text="Column Schedule Formatter | DTCE Tool Kit";Size=new Size(1420,900);MinimumSize=new Size(1100,700);Font=new Font("Segoe UI",9f);StartPosition=FormStartPosition.CenterScreen;
  var heading=new Label{Text="COLUMN SCHEDULE FORMATTER",Dock=DockStyle.Top,Height=54,Padding=new Padding(12),Font=new Font("Segoe UI",18,FontStyle.Bold),ForeColor=PowTheme.Ink};
  var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(8)};var load=new Button{Text="Load source DXF",AutoSize=true};load.Click+=(s,e)=>Choose();tools.Controls.Add(load);tools.Controls.Add(new Label{Text="Prefix",AutoSize=true,Padding=new Padding(4,8,0,0)});tools.Controls.Add(prefix);tools.Controls.Add(new Label{Text="Title",AutoSize=true,Padding=new Padding(4,8,0,0)});tools.Controls.Add(title);tools.Controls.Add(merge);tools.Controls.Add(new Label{Text="Detailing / schedule",AutoSize=true,Padding=new Padding(4,8,0,0)});tools.Controls.Add(detailing);tools.Controls.Add(new Label{Text="Extra ties",AutoSize=true,Padding=new Padding(4,8,0,0)});extraTies.Items.AddRange(new object[]{"Closed ties","Open ties (crossties)"});extraTies.SelectedIndex=0;tools.Controls.Add(extraTies);tools.Controls.Add(elevations);tools.Controls.Add(new Label{Text="Lap position",AutoSize=true,Padding=new Padding(4,8,0,0)});lapPosition.Items.AddRange(new object[]{"Slab top (above the floor)","Mid height"});lapPosition.SelectedIndex=0;tools.Controls.Add(lapPosition);lapPosition.SelectedIndexChanged+=(s,e)=>InvalidateOutput();
  var build=new Button{Text="Build preview",AutoSize=true};build.Click+=(s,e)=>Build();tools.Controls.Add(build);tools.Controls.Add(export);export.Click+=(s,e)=>Export();
  var notes=new Label{Dock=DockStyle.Top,Height=47,Padding=new Padding(10),Text="Matching columns (the same section, bars, links and ties at every level) are grouped under new marks C1, C2, ... (prefix + number) as in the sample schedule. The revised DXF is a new schedule template and loads in the Bar Bending Schedule (Column tab)."};
  var tabs=new NavigationTabs{Dock=DockStyle.Fill};var values=new TabPage("Schedule values");var layout=new TabPage("DXF preview");var panel=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.FromArgb(33,40,46)};panel.Controls.Add(cad);layout.Controls.Add(panel);values.Controls.Add(grid);values.Controls.Add(details);tabs.TabPages.Add(values);tabs.TabPages.Add(layout);
  /* the schedule as written in the drawing (owner, 22 November 2026: "yung schedule na nakasulat ayusin") */
  foreach(var h in new[]{"Column marked","Level","Section (mm)","Main bars","Lateral ties spaced at","Ties / set","Lo (mm)","Concrete / fy / cover","Original marks"})grid.Columns.Add(h,h);grid.Columns[0].Width=90;grid.Columns[0].Frozen=true;grid.Columns[1].Width=130;grid.Columns[2].Width=90;grid.Columns[3].Width=210;grid.Columns[4].Width=390;grid.Columns[5].Width=240;grid.Columns[6].Width=70;grid.Columns[7].Width=150;grid.Columns[8].Visible=false;
  grid.SelectionChanged+=(s,e)=>{details.Text=grid.CurrentRow==null?"Select a row to review its original column marks.":"Original column marks: "+Convert.ToString(grid.CurrentRow.Cells[8].Value);};grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;GridAppearance.Apply(grid);
  grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.Font=new Font("Arial",9,FontStyle.Bold);grid.ColumnHeadersDefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(20,33,51);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;grid.ColumnHeadersDefaultCellStyle.SelectionBackColor=Color.FromArgb(20,33,51);grid.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing;grid.ColumnHeadersHeight=40;grid.Font=new Font("Arial",9.5f);grid.DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(247,249,252);grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(220,240,239);grid.DefaultCellStyle.SelectionForeColor=Color.FromArgb(20,33,51);
  /* the whole header navy with white captions, as the Beam and Slab Formatters */grid.CellPainting+=(s,e)=>{if(e.RowIndex!=-1||e.ColumnIndex<0)return;using(var b=new SolidBrush(Color.FromArgb(20,33,51)))e.Graphics.FillRectangle(b,e.CellBounds);using(var p=new Pen(Color.FromArgb(210,220,230)))e.Graphics.DrawRectangle(p,e.CellBounds.Left,e.CellBounds.Top,e.CellBounds.Width-1,e.CellBounds.Height-1);TextRenderer.DrawText(e.Graphics,grid.Columns[e.ColumnIndex].HeaderText.ToUpperInvariant(),e.CellStyle.Font,Rectangle.Inflate(e.CellBounds,-4,-2),Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);e.Handled=true;};
  Controls.Add(tabs);Controls.Add(notes);Controls.Add(source);Controls.Add(tools);Controls.Add(heading);Controls.Add(status);
  prefix.TextChanged+=(s,e)=>InvalidateOutput();title.TextChanged+=(s,e)=>InvalidateOutput();merge.CheckedChanged+=(s,e)=>InvalidateOutput();elevations.CheckedChanged+=(s,e)=>InvalidateOutput();detailing.SelectedIndexChanged+=(s,e)=>InvalidateOutput();extraTies.SelectedIndexChanged+=(s,e)=>InvalidateOutput();FormClosed+=(s,e)=>{if(cad.Image!=null)cad.Image.Dispose();};FormatterChrome.Apply(this);
 #if !ADMIN_APP
  var renewal=new AccessRenewal(this);FormClosed+=(s,e)=>renewal.Dispose();
 #endif
 }
 void Guard(){if(!AccessCodes.CanUseApp(ProgramAccess.SlabFormatter))throw new Exception("Renew Schedule Formatter access.");}
 void InvalidateOutput(){result=null;export.Enabled=false;grid.Rows.Clear();if(cad.Image!=null){cad.Image.Dispose();cad.Image=null;}status.Text="Build preview to apply the current prefix, title and grouping.";}
 void Choose(){try{Guard();using(var dialog=new OpenFileDialog{Filter="Column schedule DXF|*.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK)LoadSource(File.ReadAllText(dialog.FileName),Path.GetFileName(dialog.FileName));}catch(Exception x){MessageBox.Show(this,x.Message,"Column source");}}
 internal void LoadSource(string input,string name){ColumnScheduleReader.Read(input);raw=input;source.Text="Loaded DXF: "+name;InvalidateOutput();Build();}
 void Build(){if(busy)return;busy=true;try{Guard();if(raw==null)throw new Exception("Load a column schedule DXF first.");InvalidateOutput();bool aci=AciDetailing.IsAci(detailing);Func<string,string> show=t=>aci?AciDetailing.Notation(t,"Column"):t.Replace("%%C","Ø");var built=ColumnFormatter.Build(raw,prefix.Text,title.Text,merge.Checked,aci,extraTies.SelectedIndex==1,elevations.Checked,lapPosition.SelectedIndex==1);var s=built.Schedule;
   var order=Enumerable.Range(0,s.Levels.Count).OrderBy(l=>Math.Min(s.Levels[l].FromM,s.Levels[l].ToM)).ToList();var pos=new int[s.Levels.Count];for(int q=0;q<order.Count;q++)pos[order[q]]=q;
   foreach(var g in built.Groups){var levels=Enumerable.Range(0,s.Levels.Count).Where(l=>s.Cell(g.Source[0],l)!=null).OrderBy(l=>Math.Min(s.Levels[l].FromM,s.Levels[l].ToM)).ToList();
    /* one row per drawn cell: neighbouring levels with the same section are one cell, as in the drawing */
    int k=0;while(k<levels.Count){var c=s.Cell(g.Source[0],levels[k]);int span=1;while(k+span<levels.Count&&pos[levels[k+span]]==pos[levels[k]]+span&&s.Cell(g.Source[0],levels[k+span]).Signature()==c.Signature())span++;
     var a=s.Levels[levels[k]];var b=s.Levels[levels[k+span-1]];int hoops=c.Links.Count(x=>x.W>=1&&x.H>=1),ties=c.Links.Count-hoops;
     string perSet=c.Links.Count+" (1 hoop"+(hoops>1?", "+(hoops-1)+(extraTies.SelectedIndex==1?" open":" closed")+" link"+(hoops>2?"s":""):"")+(ties>0?", "+ties+" crosstie"+(ties>1?"s":""):"")+")";
     grid.Rows.Add(g.Mark,Math.Min(a.FromM,a.ToM).ToString("0.00#")+" TO "+Math.Max(b.FromM,b.ToM).ToString("0.00#"),c.B.ToString("0")+" x "+c.H.ToString("0"),show(string.Join(" + ",c.Counts.Select(x=>x.Value+" - %%C"+x.Key+"mm"))),show("%%C"+c.TieDia+"mm: "+ColumnFormatter.TieWords(c)),perSet,c.Lo.ToString("0"),(c.Concrete==""?"-":c.Concrete)+" / "+c.Fy.ToString("0")+" / "+c.Cover.ToString("0"),g.Originals);k+=span;}}
   /* the walls (drawing and text only) */
   foreach(var w in s.Walls)foreach(var kv in w.Cells.OrderBy(q=>Math.Min(s.WallLevels[q.Key].FromM,s.WallLevels[q.Key].ToM))){var lv=s.WallLevels[kv.Key];var c=kv.Value;
    grid.Rows.Add(w.Mark,Math.Min(lv.FromM,lv.ToM).ToString("0.00#")+" TO "+Math.Max(lv.FromM,lv.ToM).ToString("0.00#"),(w.Kind==""?"WALL":w.Kind)+" ("+string.Join(", ",c.Legs.Select(q=>q.Name))+")",show(string.Join("; ",c.Legs.Where(q=>q.Bars!="").Select(q=>q.Name+": "+q.Bars.Replace("#","%%C")))),show(string.Join("; ",c.Legs.Where(q=>q.Links.Count>0).Select(q=>q.Name+": "+string.Join(", ",q.Links.Select(z=>z[0]+" "+z[1].Replace("#","%%C")))))),"","",c.Concrete,"(wall)");}
   if(grid.Rows.Count>0)details.Text="Original column marks: "+Convert.ToString(grid.Rows[0].Cells[8].Value);cad.Image=ColumnFormatter.Render(built.Sheet,4);result=built;export.Enabled=true;status.Text=built.SourceCount+" original column marks > "+built.Groups.Count+" column marks, "+s.Levels.Count+" levels | "+prefix.Text;}catch(Exception x){MessageBox.Show(this,x.Message,"Column preview");}finally{busy=false;}}
 void Export(){try{Guard();if(result==null)throw new Exception("Build preview first.");using(var dialog=new SaveFileDialog{Filter="Revised column DXF|*.dxf",FileName=prefix.Text+" Column Schedule - Revised.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){ColumnFormatter.Export(result,dialog.FileName);status.Text="Exported: "+dialog.FileName+" (load it in the Bar Bending Schedule, Column tab).";}}catch(Exception x){MessageBox.Show(this,x.Message,"Column export");}}
}
}
